#include<cstdio>
#include<cctype>
#include<queue>
#include<algorithm>
#include<cstring>
using namespace std;

#define REP(i, N) for(int i=0;i<(int)(N);++i)

int unit[20];
int need[20];

bool visited[1 << 20];

struct State {
    int one, mask, have;
};

int solve(int N, int U) {
    memset(visited, 0, sizeof(visited));
    queue<State> up;
    State s;
    s.one = 0; s.mask = 0; s.have = 0;
    visited[s.mask] = 1;
    up.push(s);
    while (!up.empty()) {
        s = up.front(); up.pop();
        if (s.have >= U) return s.one;
        for (int i = 0; i < N; i++)
            if (visited[s.mask | (1 << i)] == 0 && (s.mask | need[i]) == s.mask) {
                State next;
                next.mask = s.mask | (1 << i);
                next.one = s.one + 1;
                next.have = s.have + unit[i];
                visited[next.mask] = 1;
                up.push(next);
            }
    }
    return -1;
}

int main() {
    for (;;) {
        int N, U;
        scanf("%d %d", &N, &U);
        if (N == 0 && U == 0) break;
        REP(i, N) need[i] = 0;
        int all = 0;
        REP(i, N) {
            scanf("%d", &unit[i]);
            all += unit[i];
            int K;
            scanf("%d", &K);
            REP(k, K) {
                int x;
                scanf("%d", &x);
                need[i] |= (1 << x);
            }
        }
        if (all == U) {
            printf("%d\n", N);
            continue;
        }
        int best = solve(N, U);
        printf("%d\n", best);
    }
}

